PAGE_BITS = 12
page_table = {0x401: 0x6, 0xA: 0x12}
def translate(va):
    vpn = va >> PAGE_BITS
    offset = va & 0xFFF
    if vpn not in page_table:
        return None
    return (page_table[vpn] << PAGE_BITS) | offset
for va in [0x401234, 0xA5B6, 0x999999]:
    pa = translate(va)
    print(hex(va), '->', hex(pa) if pa is not None else 'page fault')
